import{_ as s,o as i,c as t,a2 as e}from"./chunks/framework.CZqXuAiL.js";const c=JSON.parse('{"title":"Attached IPs (Tenant Registry)","description":"","frontmatter":{},"headers":[],"relativePath":"openshield-xdp/guide/attached-ips.md","filePath":"openshield-xdp/guide/attached-ips.md","lastUpdated":null}'),n={name:"openshield-xdp/guide/attached-ips.md"};function h(l,a,d,r,p,o){return i(),t("div",null,[...a[0]||(a[0]=[e(`<h1 id="attached-ips-tenant-registry" tabindex="-1">Attached IPs (Tenant Registry) <a class="header-anchor" href="#attached-ips-tenant-registry" aria-label="Permalink to &quot;Attached IPs (Tenant Registry)&quot;">​</a></h1><p>OpenShield-XDP can learn which destination IPs actually belong to your machine — essential on dedicated servers hosting many tenant VPSes. The registry answers &quot;which of my IPs exist, and when did each last see traffic?&quot; It is <strong>informational</strong>: attaching an IP never changes how its traffic is handled, and clearing the registry never interrupts anyone.</p><h2 id="how-ips-get-attached" tabindex="-1">How IPs get attached <a class="header-anchor" href="#how-ips-get-attached" aria-label="Permalink to &quot;How IPs get attached&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Origin</th><th>How</th></tr></thead><tbody><tr><td><code>auto</code></td><td>Seen on the wire: any destination that receives more than <code>registry.auto_min_packets</code> (default 100) cumulative packets is attached automatically, plus addresses assigned to local interfaces.</td></tr><tr><td><code>manual</code></td><td>Added by you: <code>openshield ips add 203.0.113.10</code></td></tr><tr><td><code>pool</code></td><td>A whole subnet at once: <code>openshield ips pool add 203.0.113.0/24</code> — every IP in the range counts as attached without listing them individually. IPv6 pools work too.</td></tr></tbody></table><p>Noise (broadcast-looking <code>.0</code>/<code>.255</code>, multicast, link-local) is never auto-attached.</p><h2 id="last-seen-and-automatic-cleanup" tabindex="-1">Last-seen and automatic cleanup <a class="header-anchor" href="#last-seen-and-automatic-cleanup" aria-label="Permalink to &quot;Last-seen and automatic cleanup&quot;">​</a></h2><p>Every attached IP carries a <code>last seen</code> timestamp, refreshed from live traffic counters. Auto-detected entries that stay silent for <strong><code>registry.inactive_days</code></strong> (default <strong>14</strong>) are removed automatically — decommissioned tenant IPs disappear from the list on their own. Manual entries and pools are never auto-removed.</p><h2 id="managing-the-registry" tabindex="-1">Managing the registry <a class="header-anchor" href="#managing-the-registry" aria-label="Permalink to &quot;Managing the registry&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ips</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                      # table: IP, origin, first/last seen</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ips</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 203.0.113.10</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # manual attach (survives reaping)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ips</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 203.0.113.10</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;note&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # with a note</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ips</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remove</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 203.0.113.10</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ips</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clear</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                     # detach everything (harmless to traffic)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ips</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pool</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 203.0.113.0/24</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # attach a whole subnet</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ips</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pool</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remove</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 203.0.113.0/24</span></span></code></pre></div><p>The TUI shows the same list (with live per-IP rates) in the <strong>IPs</strong> tab.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">registry</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # master switch</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  inactive_days</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">14</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # auto entries silent this long are removed</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  auto_min_packets</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">100</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # wire-observed destinations need this many packets to auto-attach</span></span></code></pre></div><p>All three are runtime-safe — changes apply without reloading the firewall.</p><h2 id="why-it-matters" tabindex="-1">Why it matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;Why it matters&quot;">​</a></h2><p>The registry is what makes per-tenant features safe: <a href="./blackhole">blackhole</a> automation only ever targets <em>attached</em> IPs, so a random routed address can never be auto-blackholed, and the attacks view can tell you which tenant was actually under fire.</p>`,15)])])}const g=s(n,[["render",h]]);export{c as __pageData,g as default};
